INSERT INTO feature VALUES('exact-amplitudes','theory','Exact Clifford+T amplitudes in ℤ[1/√2, i]','ordered-algebras','partial','notable',NULL,'An amplitude is an element of `ℤ[1/√2, i]` at its least scale, so equal amplitudes have equal forms. Its sums, products, negations and conjugates are exact, and its squared modulus lies in `ℤ[1/√2]`. A coefficient past the 128-bit integers is refused, never rounded. The ring checker decides the commutative ring laws on generated amplitudes under the discrete order. The gates `H`, `S`, `T` and `CNOT` are unitary matrices over the ring, and a state vector of up to 20 qubits applies them. `std.quantum` holds the same ring in gandr, and a corpus exemplar runs `H T H` on `|0⟩` to its exact amplitudes. Measurement with the Born rule''s exact weights is the next rung.','theory-ordered-algebras','corpus/ledger/features/exact-amplitudes.gandr crates/theory-ordered-algebras/tests/amplitudes.rs crates/theory-ordered-algebras/tests/gates.rs corpus/model/quantum/amplitudes.gandr','corpus/ledger/features/exact-amplitudes.gandr','#5742');
